using MapEdit;
using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;
using ProjectTower.texturesheet;
using SheetEdit.TextureSheet;

namespace ProjectTower.particles.particles;

public class BaseParticle
{
	public virtual void Init(Particle p, Vector2 loc, Vector2 traj, float size, float rotation, int flags, int owner)
	{
		p.exists = true;
	}

	public void TrimFrame(Particle p)
	{
		if (ParticleManager.particleList[p.particleType].totalParticles > 100)
		{
			p.frame -= Game1.frameTime;
		}
		if (ParticleManager.particleList[p.particleType].totalParticles > 200)
		{
			p.frame -= Game1.frameTime;
		}
	}

	public virtual void Update(Particle p, float frameTime)
	{
		p.loc += p.traj * frameTime;
		p.frame -= frameTime;
		if (p.frame <= 0f)
		{
			p.exists = false;
		}
	}

	public virtual void Draw(Particle p, float brite)
	{
	}

	public virtual void DrawFromTexture(Vector3 loc, int idx, Vector2 scale, float rotation, float r, float g, float b, float a)
	{
		DrawFromTexture(loc, idx, scale, rotation, r, g, b, a, SpriteEffects.None);
	}

	public virtual void DrawFromTexture(Vector3 loc, int idx, Vector2 scale, float rotation, float r, float g, float b, float a, SpriteEffects se)
	{
		XSprite cell = Textures.tex[ParticleManager.spritesTexIdx].GetCell(idx);
		if (float.IsNaN(rotation))
		{
			rotation = 0f;
		}
		SpriteTools.sprite.Draw(Textures.tex[ParticleManager.spritesTexIdx].GetTexture(), ScrollManager.GetScreenLoc(loc, 0), cell.srcRect, new Color(r, g, b, a), rotation, cell.origin - new Vector2(cell.srcRect.X, cell.srcRect.Y), scale * ScrollManager.cannedDepth[0], se, 1f);
	}
}
using Microsoft.Xna.Framework;

namespace ProjectTower.particles;

public class Particle
{
	public int ID;

	public Vector2 loc;

	public Vector2 traj;

	public float size;

	public float frame;

	public float rotation;

	public int owner;

	public int flags;

	public int face;

	public int type;

	public bool exists;

	public bool grounded;

	public float rDir;

	public int aux;

	public const int PARTICLEDRAW_NORMAL = 0;

	public const int PARTICLEDRAW_ADDITIVE = 1;

	public const int PARTICLEDRAW_THRESH = 2;

	public const int PARTICLEDRAW_SUBTRACTIVE = 3;

	public int particleType;

	public int[] piercedIds = new int[3] { -1, -1, -1 };

	public Particle(int ID, int particleType)
	{
		this.ID = ID;
		this.particleType = particleType;
		exists = false;
	}

	public void Update(float frameTime)
	{
		ParticleCatalog.particle[type].Update(this, frameTime);
	}

	public void Draw(float brite)
	{
		ParticleCatalog.particle[type].Draw(this, brite);
	}

	public void Init(int type, Vector2 loc, Vector2 traj, float size, float rotation, int flags, int owner)
	{
		this.owner = -1;
		grounded = false;
		this.type = type;
		ParticleCatalog.particle[type].Init(this, loc, traj, size, rotation, flags, owner);
	}
}
using Microsoft.Xna.Framework;
using ProjectTower.character;

namespace ProjectTower.particles;

public class ParticleList
{
	public Particle[] particle;

	public int totalParticles;

	public const int BODY_PART_BASE = 2048;

	public const int BAG_BASE = 4096;

	public const int TOTAL_PARTICLES = 512;

	public const int TOTAL_SUBTRACTIVE_PARTICLES = 1024;

	public const int TOTAL_ALPHA_PARTICLES = 512;

	public const int TOTAL_ADDITIVE_PARTICLES = 1024;

	public int type;

	public ParticleList(int type)
	{
		this.type = type;
		switch (type)
		{
		case 2:
		case 5:
			particle = new Particle[1024];
			break;
		case 1:
		case 4:
			particle = new Particle[512];
			break;
		case 0:
		case 3:
			particle = new Particle[1024];
			break;
		default:
			particle = new Particle[512];
			break;
		}
		for (int i = 0; i < particle.Length; i++)
		{
			particle[i] = new Particle(i, type);
		}
	}

	internal int AddParticle(int type, Vector2 loc, Vector2 traj, float size, float rotation, int flags, int owner, bool priority)
	{
		for (int i = 0; i < particle.Length; i++)
		{
			if (!particle[i].exists)
			{
				particle[i].Init(type, loc, traj, size, rotation, flags, owner);
				if (i + 1 > totalParticles)
				{
					totalParticles = i + 1;
				}
				return i;
			}
			int num = particle[i].type;
			if (num == 1 || num == 23)
			{
				particle[i].Init(type, loc, traj, size, rotation, flags, owner);
				if (i + 1 > totalParticles)
				{
					totalParticles = i + 1;
				}
				return i;
			}
		}
		return -1;
	}

	internal int AddParticle(int type, Vector2 loc, Vector2 traj, float size, float rotation, int flags, int owner)
	{
		for (int i = 0; i < particle.Length; i++)
		{
			if (!particle[i].exists)
			{
				particle[i].Init(type, loc, traj, size, rotation, flags, owner);
				if (i + 1 > totalParticles)
				{
					totalParticles = i + 1;
				}
				return i;
			}
		}
		return -1;
	}

	internal void UpdateParticles()
	{
		int num = totalParticles;
		totalParticles = 0;
		float num2 = 0.25f;
		for (int i = 0; i < num; i++)
		{
			if (particle[i].exists)
			{
				float num3 = Game1.frameTime;
				if (particle[i].owner > -1 && particle[i].owner < 128 && CharMgr.character[particle[i].owner].exists && CharMgr.character[particle[i].owner].update.slowTime > 0f)
				{
					num3 *= num2;
				}
				particle[i].Update(num3);
				if (i + 1 > totalParticles)
				{
					totalParticles = i + 1;
				}
			}
		}
	}

	internal void Draw()
	{
		for (int i = 0; i < totalParticles; i++)
		{
			if (particle[i].exists)
			{
				particle[i].Draw(1f);
			}
		}
	}

	internal void Reset()
	{
		for (int i = 0; i < particle.Length; i++)
		{
			particle[i].exists = false;
		}
	}
}
