internal class AxeLob : BaseParticle
{
	public const int TYPE_AXE = 69;
	public const int TYPE_ARMS = 143;
	public const int TYPE_POT = 96;
	public override void Init(Particle p, Vector2 loc, Vector2 traj, float size, float rotation, int flags, int owner)
	{
		p.loc = loc;
		p.traj = traj;
		p.size = size;
		p.rotation = rotation;
		p.flags = flags;
		p.owner = owner;
		p.frame = 5f;
		p.rotation = (float)Math.PI / 2f;
		p.aux = 1;
		if (traj.X < 0f)
		{
			p.rDir = -2f;
		}
		else
		{
			p.rDir = 2f;
		}
		if (p.flags == 143)
		{
			p.rDir *= 0.5f;
		}
		if (p.flags == 96)
		{
			float num = 600f;
			if (p.traj.X < 0f - num)
			{
				p.traj.X = 0f - num;
			}
			if (p.traj.X > num)
			{
				p.traj.X = num;
			}
		}
		base.Init(p, loc, traj, size, rotation, flags, owner);
	}
	public override void Update(Particle p, float frameTime)
	{
		float frame = p.frame;
		p.traj.Y += frameTime * 2500f;
		if (CharCols.TestCol(p.loc, falling: false, 0f))
		{
			p.exists = false;
		}
		if (p.aux == 1 && HitManager.CheckHit(p))
		{
			p.aux = 0;
			p.traj.X *= -0.1f;
			p.traj.Y = Rand.GetRandomFloat(-400f, -600f);
		}
		p.rotation += p.rDir * frameTime * 20f;
		base.Update(p, frameTime);
		if (!p.exists)
		{
			return;
		}
		if ((int)(p.frame * 60f) != (int)(frame * 60f))
		{
			switch (p.flags)
			{
			case 143:
				if ((int)(frame * 60f) != (int)(p.frame * 60f))
				{
					if (Rand.CoinToss(0.5f))
					{
						ParticleManager.AddSubtractiveParticle(4, p.loc, Rand.GetRandomVec2(-1f, 1f, -1f, 1f) * 100f, Rand.GetRandomFloat(0.1f, 1.5f) * 0.95f, 0f, 0, -1);
					}
					else
					{
						ParticleManager.AddNormalParticle(13, p.loc, Rand.GetRandomVec2(-1f, 1f, -1f, 1f) * 100f, Rand.GetRandomFloat(0.1f, 1.5f) * 0.95f, 0f, 0, -1);
					}
				}
				break;
			case 96:
				if (p.frame > 4f)
				{
					ParticleManager.AddSubtractiveParticle(0, p.loc, Rand.GetRandomVec2(-1f, 1f, -1f, 1f) * 100f, Rand.GetRandomFloat(0.1f, 0.7f) * (p.frame - 4f), 0f, 0, -1);
				}
				break;
			}
		}
		if (p.frame > 4.9f && (int)(p.frame * 60f) != (int)(frame * 60f))
		{
			ParticleManager.AddNormalParticle(7, p.loc, p.traj * 0.01f, Rand.GetRandomFloat(0.5f, 1f) * (5f - p.frame) * 10f, 0f, 0, -1);
		}
	}
	public override void Draw(Particle p, float brite)
	{
		float r = 1f;
		float g = 1f;
		float b = 1f;
		if (p.flags == 96)
		{
			g = 0.5f;
		}
		Vector2 screenLoc = ScrollManager.GetScreenLoc(p.loc, 0);
		Textures.tex[ParticleManager.spritesTexIdx].Draw(screenLoc, p.flags, new Vector2(1f, 1f) * ScrollManager.cannedDepth[0] * 0.5f, p.rotation, r, g, b, p.frame * 2f);
		if (p.flags == 96)
		{
			Textures.tex[ParticleManager.spritesTexIdx].Draw(screenLoc, 0, ScrollManager.cannedDepth[0] * new Vector2(1f, 1f), 0f, 1f, 0f, 1f, 0.5f);
		}
		base.Draw(p, brite);
	}
}
