	public XTexture(BinaryReader reader, ContentManager Content)
	{
		name = reader.ReadString();
		ReadData(reader);
		switch (type)
		{
		case 1:
		case 4:
			isLoaded = false;
			isLoading = false;
			break;
		case 0:
			switch (name)
			{
			case "sprites":
			case "swooshes":
			case "logosegs":
			case "smashables":
			case "smashbits":
				texture = Content.Load<Texture2D>("gfx/" + name);
				isLoaded = true;
				break;
			default:
				isLoaded = false;
				isLoading = false;
				break;
			}
			break;
		default:
			texture = Content.Load<Texture2D>("gfx/" + name);
			isLoaded = true;
			break;
		}
	}
	public bool IsLoaded()
	{
		if (needsUnload)
		{
			if (isLoading)
			{
				return false;
			}
			needsUnload = false;
			isLoaded = false;
		}
		if (!isLoaded && !isLoading)
		{
			Point point = UGCManager.CheckReplace(name);
			ugcPackageIdx = point.X;
			ugcSheetIdx = point.Y;
		}
		if (isLoaded)
		{
			return true;
		}
		if (isLoading)
		{
			return false;
		}
		if (StorageJobMgr.busy)
		{
			return false;
		}
		if (StorageJobMgr.timeOut > 0f)
		{
			return false;
		}
		isLoading = true;
		isLoaded = false;
		Thread thread = new Thread(ThreadedLoader);
		try
		{
			thread.Start();
		}
		catch
		{
		}
		return false;
	}
	private void ThreadedLoader()
	{
		while (Textures.loading)
