	public SheetUGCPackage(string directory, string filename, string name, string description, string tags, string meta, string previewPath)
	{
		Init(directory, filename, name, description, tags, meta, previewPath);
	}
	public void Init(string directory, string filename, string name, string description, string tags, string meta, string previewPath)
	{
		this.directory = directory;
		fileName = filename;
		this.name = name;
		this.description = description;
		this.tags = tags;
		this.meta = meta;
		this.previewPath = previewPath;
